package com.proofclean.analysis.controller;
import com.proofclean.analysis.dto.*;import com.proofclean.analysis.service.AnalysisService;import lombok.RequiredArgsConstructor;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.util.List;
@RestController @RequestMapping("/api/analyses") @RequiredArgsConstructor
public class AnalysisController { private final AnalysisService analysisService; private String email(Authentication a){return a.getName();} @GetMapping public List<AnalysisResponse> list(Authentication a){return analysisService.list(email(a));} @PostMapping public AnalysisResponse create(Authentication a,@RequestBody AnalysisCreateRequest req){return analysisService.create(email(a),req);} @GetMapping("/{id}") public AnalysisDetailResponse detail(Authentication a,@PathVariable Long id){return analysisService.detail(email(a),id);} @PostMapping("/{id}/files") public UploadedFileResponse upload(Authentication a,@PathVariable Long id,@RequestParam MultipartFile file){return analysisService.upload(email(a),id,file);} @PostMapping("/{id}/run") public AnalysisRunResponse run(Authentication a,@PathVariable Long id){return analysisService.run(email(a),id);} @GetMapping("/{id}/findings") public List<DetectionDto> findings(Authentication a,@PathVariable Long id){return analysisService.findings(email(a),id);} @GetMapping("/{id}/scenarios") public List<RiskScenarioDto> scenarios(Authentication a,@PathVariable Long id){return analysisService.scenarios(email(a),id);} @GetMapping("/{id}/recommendations") public List<RecommendationDto> recommendations(Authentication a,@PathVariable Long id){return analysisService.recommendations(email(a),id);} @PostMapping("/{id}/mask") public MaskedFileResponse mask(Authentication a,@PathVariable Long id){return analysisService.mask(email(a),id);} }
